<span class="line"><span style="color:#ABB2BF;">    x </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> np.</span><span style="color:#61AFEF;">clip</span><span style="color:#ABB2BF;">(x </span><span style="color:#56B6C2;">*</span><span style="color:#D19A66;"> 255.0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">255</span><span style="color:#ABB2BF;">).</span><span style="color:#61AFEF;">astype</span><span style="color:#ABB2BF;">(np.uint8)</span></span>
